UPDATE INT_SERVERFUNCTION SET NAME = COALESCE(NULL, NAME), DESCRIPTION = COALESCE('ORCAMENTO por CR/mes do pacote (por nome do driver, escapado).', DESCRIPTION), TYPE = COALESCE(NULL, TYPE), JDBC_ID = NULL, CODE = COALESCE('SELECT CR_ID, MES, SUM(VALOR) as VALOR FROM ORCAMENTO WHERE CICLO_ID = {{cicloId}} AND DRIVER_TIPO = ''{{pkgNome}}'' GROUP BY CR_ID, MES', CODE), PUBLIC_EXECUTION = COALESCE(NULL, PUBLIC_EXECUTION), CRON_EXPRESSION = NULL, CRON_INPUT_JSON = NULL WHERE NAME = 'hotPkgCrOrcamento';
